# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: digest
def digest(xs, offset=1):
    return [v + offset for v in xs]

# region: render
def render(xs, factor=3):
    return [v * factor for v in xs]

# region: gather
def gather(xs, offset=1):
    return [v - offset for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(fold(gather(render(digest(intake(raw))))))

